/*
    ----------------------------------------------------------
    New: 
    - other fractal with more transformations
    - mobile responsiveness for fullscreen
    ----------------------------------------------------------
    This shader is based on my previous shaders in an attempt 
    to make the fractals configurable.
    Random fractals appear by clicking/tapping anywhere on the 
    fractal part of the screen.
    The parameters leading to the shown fractal
    will then be shown on the right.
    No names obviously, but at least the value of each 
    slider/rotator. 
    Clicking on the ui elements is possible 
    for changing parameters and getting a morphed version of the previous random fractal.
    The rotators are for angular parameters for rotational transformations
    and for the fun of having a different ui element ;-)

    The shader is based on sdf distance calculations by inigo quilez
    and on saving state in a buffer based on the bricks game written by inigo quilez.
    The digits are from p_malin.
    Each imported code has the source mentioned right before its start.
    ----------------------------------------------------------
*/

// Render controls
#define AA 0.0
#define DEBUG 0

// Global for size of board
float S;

vec2 getIResolution(){
    vec2 r = iResolution.xy;
    if(r.x < r.y){
        r = r.yx;
    }
    return r;
}

vec4 loadValue(in ivec2 re){
    return texelFetch(iChannel0, re, 0);
}

void drawSlider(in vec2 p, inout vec3 c, inout float dist, in E e, in float v){
    // Outline
    dist = sd2DBox(p - S * (e.pos + 0.5 * e.size), 0.5 * S * e.size);
    dist = abs(dist) - B2 * S;
    c += step(dist, 0.0) * C_BORDER;
    // Inner
    vec2 size = e.size * vec2(v, 1.0) - B2 * 2.0;
    float d = sd2DBox(p - S * (e.pos + 0.5 * size + B2), 0.5 * S * size);
    dist = min(d, dist);
    c += step(d, 0.0) * mix(e.colorA, e.colorB, v);
}

void drawButton(in vec2 p, inout vec3 c, inout float dist, in E e){
    // Outline
    dist = sd2DBox(p - 0.5 * S * (2.0 * e.pos + e.size), 0.5 * S * e.size);
    dist = abs(dist) - B2 * S;
    c += step(dist, 0.0) * C_BORDER;
    // Inner
    vec2 size = e.size - B2 * 2.0;
    float d = sd2DBox(p - S * (e.pos + 0.5 * e.size), 0.5 * S * size);
    dist = min(d, dist);
    c += step(d, 0.0) * e.colorA;
}
void drawToggle(in vec2 p, inout vec3 c, out float dist, in E e, in float value){
    // Outline
    vec2 b = 0.5 * S * e.size;
    vec2 pos = S * e.pos + b.y;
    dist = sd2DLine(p, pos, pos + vec2(b.x + b.y, 0.0)) - b.y;
    dist = abs(dist) - B2 * S;
    c += step(dist, 0.0) * C_BORDER;
    // Inner
    pos.x += value * (b.x - b.y * 0.75);
    float d = sd2DLine(p, pos, pos + vec2(b.x - b.y, 0.0)) - b.y + B2 * S;
    c += step(d, 0.0) * mix(e.colorA, e.colorB, value);
}
void drawRotator(in vec2 p, inout vec3 c, out float dist, in E e, in float value){
    vec2 center = p - S * e.pos - 0.5 * S * e.size.x;
    // Outline
    dist = length(center) - 0.5 * S * e.size.x;
    dist = abs(dist) - B2 * S;
    c += step(dist, 0.0) * C_BORDER;
    // steps
    vec2 c2 = center;
    float d = length(center) - 3.0 * B2 * S;
    float mp = pModPolar(c2, 18.0);
    c2 = -c2 + p;
    d = min(d, sd2DLine(p, c2 + S * vec2(2.0 * B, 0.0), c2 + e.size.y * S * vec2(0.4, 0.0)) - 0.5 * B2 * S);
    c += step(d, 0.0) * e.colorA;
    dist = min(dist, d);
    // Current degrees position
    center = -center + p;
    float vc = PI * 2.0 * value - PI;
    float d2 = sd2DLine(p, center, center +  0.5 * e.size.x * S * vec2(cos(vc), sin(vc))) - 2.0 * B2 * S;
    dist = min(dist, d2);
    c += step(d2, 0.0) * e.colorB;
}

float getValue(in int i){
    if(i >= 0 && i < G){
        return loadValue(ivec2(i, 0)).x;
    }
    return 0.0;
}
void printValue(inout vec3 col, in vec2 p, in float v, float s, in float s2, in int maxD){
    if(maxD == 1){
        v += 0.1;
    }
    bool neg = v < 0.0;
    v = abs(v + sign(v) * 0.0000003 * abs(v)); // to prevent 1.0 be shown as 1.9999999 or -1.5 as - 1.4999999
    int fDigits, pDigits;
    fDigits = v < 1.0 ? 1 : int(ceil(log10(v)));
    pDigits = maxD - fDigits;
    float add = 0.5;
    if(neg){
        col += C_FONT * step(sd2DBox(p - s - vec2(0.0, 0.5 * s), s2 * vec2(2.0, 0.5)), 0.0);
    }
    if(fDigits > 0){
        float f = v;
        col += C_FONT * float(PrintInt(fDigits, (p - vec2(s + add * s, s)) / s, int(f)));    
    }
    if(maxD == 1){
        return;
    }
    col += step(sd2DBox(p - vec2((float(fDigits) + 1.0 + add) * s, s * 1.1), vec2(s2 * 0.5)), 0.0);
    p.x -= float(fDigits) * s * 1.2;
    if(pDigits > 0){
        float f = v * pow(10.0, float(pDigits));
        col += C_FONT * float(PrintInt(pDigits, (p - vec2(s + add * s, s)) / s, int(f)));
    }
}

void applyRange(E e, out float result, in float v){
    result = e.mini + v * (e.maxi - e.mini);
}
void rotateMod(inout vec2 p, inout float r, in float a, in float m){
    r = mod(r + a, m);
    rotate(p, r);
}
float FractalGenerator2D(vec2 q) {
    // Init parameters
    float par[G] = float[G](M, M, M, M, M, M, M, M, M, M, M, M, M, M, M);
    for(int i = 0; i < G; i++){
        par[i] = getValue(i);
        applyRange(elements[i], par[i], par[i]);
    }
    float d = 1e8;
    //Fractal
	float w = pModPolar(q, par[4]);
    vec3 p = vec3(q, par[6]);
    p = abs(p) - par[12];     
    float rot = 0.0;
    if(par[1] >= 0.5){
    if(p.x < p.z){
        p.xz = p.zx;  
    }
    if(p.y < p.z){
        p.yz = p.zy; 
    }
    if(p.x < p.y){
        p.xy = p.yx;   
    }
    }
    float s = par[13];    
    for(float i = 0.0; i < par[5]; i++){    
        float r2 = par[14] / clamp(dot(p,p), par[7], par[8]);  
        if(par[0] >= 0.5){
            rotateMod(p.xy, rot, par[2], par[3]);
		    rotateMod(p.yz, rot, par[2], par[3]);
		    rotateMod(p.zx, rot, par[2], par[3]);
		}
		p = abs(p) * r2 - vec3(par[9], par[10], par[11]);    
        if(par[0] >= 0.5){
            rotateMod(p.zx, rot, -par[2], par[3]);
		    rotateMod(p.yz, rot, -par[2], par[3]);
		    rotateMod(p.xy, rot, -par[2], par[3]);
        }
		s *= r2;    
    }    
    d = length(p) / s; 
    return d;
}

vec3 palette(in float t) {
	return palette(t, vec3(0.5, 0.48, 0.4), vec3(0.5), vec3(0.95, 0.99, 0.95), vec3(0.0, 0.14, 0.32));
}
void drawFractal(inout vec3 c, in vec2 q){
    // Outline
    float d = sd2DBox(q, vec2(S)); // TODO
    // Fractal with vignette 
    float fg = FractalGenerator2D(q);
    if(d < 0.0){
        float ex = clamp(2.0 * (1.0 - exp(d * 0.01)), 0.0, 1.0);
        c += ex * clamp(palette(mod(fg * 4.0, 6.0)), 0.0, 1.0);
    }
    d = abs(d) - 2.0;
    c += step(d, 0.0) * C_BORDER;
}

vec3 drawBoard(in vec2 p, out float dist){
    // Correct upside down
    p.y = S - p.y;
    // Get position for printing values
    vec2 q = p / S;
    // Draw elements
    vec3 c = vec3(0.0);
    float distTmp;
    for(int i = 0; i < G; i++){
        E e = elements[i];
        float v;
        applyRange(e, v, getValue(i));
        if(e.type == BUTTON){drawButton(p, c, distTmp, e);}
        if(e.type == SLIDER){
            drawSlider(p, c, distTmp, e, getValue(i));
            printValue(c, vec2(q.x - e.pos.x + B, (1.0 - q.y) - (1.0 - e.pos.y) + 1.25 * e.size.y), v, B * 1.5, B2 * 1.5, i == 4 || i == 5 ? 1 : 7);
        }
        if(e.type == TOGGLE){drawToggle(p, c, distTmp, e, getValue(i) < 0.5 ? 0.0 : 1.0);}
        if(e.type == ROTATOR){
            drawRotator(p, c, distTmp, e, getValue(i));
            printValue(c, vec2(q.x - e.pos.x + B * 0.5, (1.0 - q.y) - (1.0 - e.pos.y) + 1.45 * e.size.y), v, B * 1.1, B2 * 1.1, 5);
        }
        dist = min(dist, distTmp);
    }    
    // Adjust for better looks
    dist = 1.0 - exp(dist * 0.5);
    return c;
}

void renderBoard(in vec2 p, out vec3 col){
    // For pseudo 3D effects use differences
    const float eps = 1e-3;
    vec3 dx = vec3(eps, 0.0, 0.0);
    vec3 dy = dx.yxz;
    vec3 d0 = dx.zzz;
    col += drawBoard(p, d0.z);
    drawBoard(p - dx.xy * S, dx.z);
    drawBoard(p - dy.xy * S, dy.z);
    dx.z = d0.z - dx.z;
    dy.z = d0.z - dy.z;
    // Diffuse lighting 
    vec3 n = normalize(cross(dx ,dy));
    const vec3 lightDir = normalize(vec3(0.25, 1.0, 0.75));
    col *= 0.5 + 0.5 * dot(n, lightDir);
    col *= 0.5 + 0.5 * d0.z;
    col = clamp(col * 2.0, 0.0, 1.0);
    // Postprocess
    col = pow(col, vec3(0.45));
}

void render(inout vec3 col, in vec2 p, in vec2 s){
    bool rev = false;
    if(s.x < s.y){
        s = s.yx;
        p = s - p.yx;
        rev = true;
    }
    // Set global board size
    S = s.y;
    if(p.x > s.x - s.y){
        // Draw fractal without antialiasing
        p = 2.0 * vec2(p.x - s.x + s.y, p.y) / s.y - 1.0;
        drawFractal(col, p);
        #if DEBUG == 1
        col = vec3(0.4);
        #endif
    }else{
        if(rev){p = s.y - p.yx;}
        // Draw board with antialiasing 
        float n = AA;
        float w = 0.25 / iResolution.y;
        for(float i = -n; i <= n; i++){
            for(float j = -n; j <= n; j++){
                vec3 c;
                renderBoard(p + w * vec2(i, j), c);
                col += c;
            }
        }
        // Divide sum of multiple samples
        n = 2.0 * n + 1.0;
        n = n * n;
        col /= n;
        #if DEBUG == 1
        col = vec3(0.8);
        #endif
    }    
}
void mainImage(out vec4 c, in vec2 uv){
    vec3 col = vec3(0.0);
    vec2 res = iResolution.xy;
    render(col, uv, res);
    #if DEBUG == 7
    // Border
    float rr = 4.0;
    if(uv.x < rr || uv.y < rr || uv.x > res.x-rr || uv.y > res.y-rr){
        col = vec3(16.0,64.0,128.0) / 256.0;
    }
    #endif
    c = vec4(col, 1.0);

}

// Element API
#define BUTTON 1
#define SLIDER 2
#define TOGGLE 3
#define ROTATOR 4
#define C_TOGGLE_A vec3(1.0, 0.0, 0.0)
#define C_TOGGLE_B C_TOGGLE_A.yxz
#define C_ROTATOR_A vec3(0.5, 0.2, 0.5)
#define C_ROTATOR_B vec3(1.0, 1.0, 0.2)
#define C_SLIDER_A vec3(0.5, 0.1, 0.0)
#define C_SLIDER_B C_SLIDER_A.yxz
#define C_BUTTON vec3(0.1, 0.3, 0.5)
#define C_BORDER vec3(0.0, 0.6, 1.0)
#define C_FONT vec3(0.8, 0.9, 1.0)
struct E{
    vec3 colorA, colorB;
    float mini, maxi;
    vec2 pos, size;
    int type;
};
#define cButton(color, pos, size) E(color, color, 0.0, 1.0, pos, size, BUTTON)
#define cSlider(colorA, colorB, mini, maxi, pos, size) E(colorA, colorB, mini, maxi, pos, size, SLIDER)
#define cToggle(colorA, colorB, pos, size) E(colorA, colorB, 0.0, 1.0, pos, size, TOGGLE)
#define cRotator(colorA, colorB, mini, maxi, pos, size) E(colorA, colorB, mini, maxi, pos, size, ROTATOR)

// Element instances
#define G 15
#define SL 0.098
#define B (SL * 0.25)
#define B2 (B * 0.2)
const vec2 SSXY = SL * vec2(7.0, 0.75);
const vec2 SSXY2 = SSXY * vec2(0.475, 1.0);
const E elements[G] = E[G](
    cToggle(C_TOGGLE_A, C_TOGGLE_B, vec2(B, B), SL * vec2(2.75, 1.0)),
    cToggle(C_TOGGLE_A, C_TOGGLE_B, vec2(B, B + SL * 1.25), SL * vec2(2.75, 1.0)),
    cRotator(C_ROTATOR_A, C_ROTATOR_B, 0.0, 30.0, vec2(B + SL * 3.25, B), vec2(1.75 * SL)),
    cRotator(C_ROTATOR_A, C_ROTATOR_B, 10.0, 60.0, vec2(B + SL * 5.25, B), vec2(1.75 * SL)),
    cSlider(C_SLIDER_A, C_SLIDER_B, 3.0, 11.0, vec2(B, B + SSXY.y * 3.5), SSXY), 
    cSlider(C_SLIDER_A, C_SLIDER_B, 4.0, 10.0, vec2(B, B + SSXY.y * 4.7), SSXY), 
    cSlider(C_SLIDER_A, C_SLIDER_B, 0.2, 1.8, vec2(B, B + SSXY.y * 5.9), SSXY), 
    cSlider(C_SLIDER_A, C_SLIDER_B, 0.05, 0.5, vec2(B, B + SSXY.y * 7.1), SSXY), 
    cSlider(C_SLIDER_A, C_SLIDER_B, 1.25, 1.75, vec2(B, B + SSXY.y * 8.3), SSXY), 
    cSlider(C_SLIDER_A, C_SLIDER_B, 0.1, 1.0, vec2(B, B + SSXY.y * 9.5), SSXY2), 
    cSlider(C_SLIDER_A, C_SLIDER_B, 0.3, 3.0, vec2(B + SSXY2.x * 1.1, B + SSXY.y * 9.5), SSXY2), 
    cSlider(C_SLIDER_A, C_SLIDER_B, 0.6, 6.0, vec2(B, B + SSXY.y * 10.7), SSXY2), 
    cSlider(C_SLIDER_A, C_SLIDER_B, 0.75, 2.0, vec2(B + SSXY2.x * 1.1, B + SSXY.y * 10.7), SSXY2), 
    cSlider(C_SLIDER_A, C_SLIDER_B, 1.0, 2.0, vec2(B, B + SSXY.y * 11.9), SSXY2), 
    cSlider(C_SLIDER_A, C_SLIDER_B, 2.0, 4.0, vec2(B + SSXY2.x * 1.1, B + SSXY.y * 11.9), SSXY2)
);

// Storage
#define tx1 ivec4(0,0,G,1)
#define M -1e6

// Helper
#define PI 3.141593
bool isInRange(in vec2 pw, in float v){
    return pw.x <= v && pw.x + pw.y >= v;
}
bool isInBox(in vec4 box01, in vec2 p01){
    return isInRange(box01.xz, p01.x - B2) && isInRange(box01.yw, p01.y);
}
void rotate(inout vec2 q, in float deg){
    float rad = radians(deg);
    q = mat2x2(cos(rad),sin(rad),-sin(rad),cos(rad)) * q;
}
const float lg110 = 1.0 / log(10.0);
float log10(in float v){
    return log(v) * lg110;
}
vec3 firePalette(in float t){
    t = pow(abs(4.0 * PI * t), 0.5);
    float r = abs(sin(t));
    vec3 c = vec3(r, 0.0, 0.0);
    c.g += abs(1.5 * sin(max(0.0, 2.0 * r - 1.5)));
    return c;
}

//-----------------------------------------------------------------------------------------------------------------------
// External
//-----------------------------------------------------------------------------------------------------------------------
// Source: https://iquilezles.org/articles/distfunctions2d/
float sd2DBox( in vec2 p, in vec2 b ){
    vec2 d = abs(p)-b;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}
float sd2DLine( in vec2 p, in vec2 a, in vec2 b ){
    vec2 pa = p-a, ba = b-a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    return length( pa - ba*h );
}
// Source: https://iquilezles.org/articles/palettes/
vec3 palette( in float t, in vec3 a, in vec3 b, in vec3 c, in vec3 d ){
    return a + b*cos( 6.28318*(c*t+d) );
}

// Based on https://www.shadertoy.com/view/WsV3zz
float hash(int n) {
	n = (n << 13) ^ n;
    n = n * (n * n * 15731 + 789221) + 1376312589;
    return float(n & ivec3(0x0fffffff))/float(0x0fffffff);
}
float gnoise(in float p){
    int i = int(floor(p));
    float f = fract(p);
    float u = f*f*(3.0-2.0*f);
    return mix(hash(i + 0) * (f - 0.0), hash(i + 1) * (f - 1.0), u);
}
float fbm(in float x, in float g){    
    float n = 0.0;
    float s = 1.0;
    float f = 1.0;
    float sum = 0.0;
    for(int i = 0; i < 7; i++){
        n += s * gnoise(x * f);
        sum += s;
        s *= g;
        f *= 2.2;
    }
    n /= sum;
    return n;
}
float getFbm(in float f){
    return clamp(fbm(f, 0.5) * 6.0 + 0.5, 0.0, 1.0);
}

// From https://www.shadertoy.com/view/XdjyRm
float pModPolar(inout vec2 p, float repetitions) {
	float angle = 2.*3.141592654/repetitions;
	float a = atan(p.y, p.x) + angle/2.;
	float r = length(p);
	float c = floor(a/angle);
	a = mod(a,angle) - angle/2.;
	p = vec2(cos(a), sin(a))*r;
	// For an odd number of repetitions, fix cell index of the cell in -x direction
	// (cell index would be e.g. -5 and 5 in the two halves of the cell):
	if (abs(c) >= (repetitions/2.)) c = abs(c);
	return c;
}

// From (only made number of digits flexible): P_Malin (https://www.shadertoy.com/view/4sf3RN) (https://www.shadertoy.com/view/43GcR1)
const int[] font = int[](0x75557, 0x22222, 0x74717, 0x74747, 0x11574, 0x71747, 0x71757, 0x74444, 0x75757, 0x75747);
const int[] powers = int[](1, 10, 100, 1000, 10000, 100000);
int PrintInt(in int maxDigits, in vec2 uv, in int value ){
    if( abs(uv.y-0.5)<0.5 ){
        int iu = int(floor(uv.x));
        if( iu>=0 && iu<maxDigits ){
            int n = (value/powers[maxDigits-iu-1]) % 10;
            uv.x = fract(uv.x);
            ivec2 p = ivec2(floor(uv*vec2(4.0,5.0)));
            return (font[n] >> (p.x+p.y*4)) & 1;
        }
    }
    return 0;
}

float getValue(in E e, in vec2 m01, int i){
   float v = 1.0 - (e.pos.x + e.size.x - m01.x) / e.size.x;
   if(e.type == SLIDER){
       if(i == 4 || i == 5){
           v = round(e.mini + v * (e.maxi - e.mini));
           v = (v - e.mini) / (e.maxi - e.mini);
       }
       return v;
   }
   if(e.type == TOGGLE){return v < 0.5 ? 0.0 : 1.0;}
   if(e.type == ROTATOR){
       float vy = 1.0 - (e.pos.y + e.size.y - m01.y) / e.size.y;
       float a = atan(vy - 0.5, v - 0.5);
       return (a / 3.141592654 + 1.0) * 0.5;
   }
   return 0.5;
}

// Based on https://www.shadertoy.com/view/43GcR1
// Storage register/texel addresses
const ivec4 txPar = ivec4(0,0,G,1);
const ivec2 txRnd = ivec2(G+1,0);

vec4 loadValue(in ivec2 re){
    return texelFetch(iChannel0, re, 0);
}
void storeValue(in ivec2 re, in vec4 va, inout vec4 fragColor, in ivec2 p){
    fragColor = (p == re) ? va : fragColor;
}
void storeValue(in ivec4 re, in vec4 va, inout vec4 fragColor, in ivec2 p){
    fragColor = (p.x >= re.x && p.y >= re.y && p.x <= re.z && p.y <= re.w) ? va : fragColor;
}
void save(in ivec2 tx, in vec3 v, inout vec4 fragColor, in ivec2 p){
    storeValue(tx, vec4(v, 0.0), fragColor, p);
}
void load(in ivec2 tx, out vec3 v){
    v = loadValue(tx).xyz;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord ){
    ivec2 ipx = ivec2(fragCoord - 0.5);
    // Don't compute outside of the data area
    if(fragCoord.x > float(G + 2) || fragCoord.y > 1.0){
        discard;
    }
    // Load
    float par = loadValue(ivec2(fragCoord.x, 0.0)).x;
    float rnd = loadValue(txRnd).x;
    // Reset
    if(iFrame == 0){
        storeValue(txPar, vec4(1.0, 0.0, 0.0, 0.0), fragColor, ipx);
    }
    // Base
    fragColor = vec4(0.0);
    storeValue(ipx, vec4(par, 0.0, 0.0, 0.0), fragColor, ipx);
    float offset = 184.947;
    // Input
    vec2 SIZE = iResolution.xy;
    vec2 mouse01 = iMouse.xy / SIZE.xy;
    /*
        Get random fractal parameters based on position of mouse, 
        but offset each time with a random float to get an new set of parameters even when clicking on the same spot.
    */
    if(SIZE.x < SIZE.y){
        float zero = SIZE.x / SIZE.y;
        if(mouse01.y < zero){
            float v = clamp(getFbm(offset + (mouse01.x * 252.352 + mouse01.y * 626.923 + rnd) / (float(ipx.x) + 2.46)), 0.0, 1.0);
